const quoteDefaults=()=>({quoteNo:`QT-${new Date().toISOString().slice(0,7).replace('-','')}-001`,customer:'待填写客户',contact:'',currency:'CNY',taxRate:.13,freight:0,leadTime:'12 - 15 个工作日',validDays:15,paymentTerms:'预付款 50%，发货前付清尾款',notes:'报价基于已解析的 B-Rep 几何、材料和工艺假设；公差、热处理、装夹与特殊检验要求以确认图纸为准。'});
state.quoteMeta??=quoteDefaults();
function quoteMeta(){state.quoteMeta??=quoteDefaults();return state.quoteMeta}
function roundMoney(value){return Math.round((Number(value||0)+Number.EPSILON)*100)/100}
function partCost(item){const basis=quoteBasis(item),qty=Math.max(1,Number(item.quantity)||1),cfg=item.costConfig||{},material=Math.max(0,Number(cfg.materialCost??basis.materialCost*1.18)),machining=Math.max(0,Number(cfg.machiningCost??basis.machiningHours*basis.machineRate)),setup=Math.max(0,Number(cfg.setupCost??basis.setupCost)),finish=Math.max(0,Number(cfg.finishCost??0)),inspection=Math.max(0,Number(cfg.inspectionCost??18)),overheadRate=Math.max(0,Number(cfg.overheadRate??.1)),marginRate=Math.max(0,Number(cfg.marginRate??.15)),direct=material+machining+setup/qty+finish+inspection,overhead=direct*overheadRate,autoUnit=(direct+overhead)*(1+marginRate),manual=Number(item.unitPrice)||0,mode=item.priceMode||'auto',unit=roundMoney(mode==='manual'&&manual>0?manual:autoUnit);return{basis,qty,material,machining,setup,finish,inspection,overheadRate,marginRate,direct,overhead,autoUnit,unit,line:roundMoney(unit*qty),mode}}
function quoteTotals(){const lines=state.files.filter(file=>file.part).map(partCost),goods=roundMoney(lines.reduce((sum,line)=>sum+line.line,0)),meta=quoteMeta(),freight=roundMoney(Math.max(0,Number(meta.freight)||0)),tax=roundMoney((goods+freight)*Math.max(0,Number(meta.taxRate)||0));return{lines,goods,freight,tax,total:roundMoney(goods+freight+tax)}}
function money(value){return `¥${Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
