function buildQuoteEditor(item){const c=partCost(item);$('#quoteEditor').innerHTML=`<button id="quoteBackdrop" class="quote-backdrop" aria-label="关闭零件设置"></button><section class="quote-drawer quote-drawer-v2"><header><div><small>PART COST CONFIGURATION</small><h2>零件报价配置</h2><p>${esc(cadDisplayName(item))}</p></div><button id="quoteClose" aria-label="关闭">×</button></header><div class="quote-form"><section class="quote-price-mode"><button type="button" data-price-mode="auto" class="${c.mode==='auto'?'active':''}"><b>自动核算</b><span>成本构成 + 利润率</span></button><button type="button" data-price-mode="manual" class="${c.mode==='manual'?'active':''}"><b>手动单价</b><span>锁定对外报价</span></button></section><div class="quote-pair"><label>材料<select id="qMaterial">${Object.keys(materialDensities).map(name=>`<option ${name===(item.material||'Aluminum 6061')?'selected':''}>${name}</option>`).join('')}</select></label><label>表面处理<select id="qFinish"><option>As Machined</option><option>Anodizing (Clear)</option><option>Anodizing (Black)</option><option>Powder Coating</option><option>Passivation</option></select></label></div><div class="quote-pair"><label>数量<input id="qQuantity" type="number" min="1" value="${c.qty}"></label><label>版本<input id="qRevision" value="${esc(item.revision||'A')}"></label></div><section class="cost-breakdown"><div class="cost-heading"><span>单件成本构成</span><em>可直接调整</em></div><label>材料与毛坯<input id="qMaterialCost" type="number" min="0" step=".01" value="${c.material.toFixed(2)}"></label><label>机加工<input id="qMachiningCost" type="number" min="0" step=".01" value="${c.machining.toFixed(2)}"></label><label>装夹 / 编程（按批分摊）<input id="qSetupCost" type="number" min="0" step=".01" value="${c.setup.toFixed(2)}"></label><label>表面与后处理<input id="qFinishCost" type="number" min="0" step=".01" value="${c.finish.toFixed(2)}"></label><label>首检 / 质检<input id="qInspectionCost" type="number" min="0" step=".01" value="${c.inspection.toFixed(2)}"></label><div class="quote-pair"><label>制造管理费 %<input id="qOverhead" type="number" min="0" step=".1" value="${(c.overheadRate*100).toFixed(1)}"></label><label>利润率 %<input id="qMargin" type="number" min="0" step=".1" value="${(c.marginRate*100).toFixed(1)}"></label></div></section><label class="manual-price">对外单价<input id="qUnitPrice" type="number" min="0" step=".01" value="${(c.mode==='manual'?c.unit:c.autoUnit).toFixed(2)}"></label><div class="quote-subtotal quote-subtotal-v2"><div><span>本批单件报价</span><small id="qCostHint"></small></div><b id="qSubtotal">${money(c.line)}</b></div><button id="quoteSave" class="quote-save">保存到项目报价</button></div></section>`;
 const refresh=()=>{const qty=Math.max(1,Number($('#qQuantity').value)||1),manual=Math.max(0,Number($('#qUnitPrice').value)||0),material=Math.max(0,Number($('#qMaterialCost').value)||0),machining=Math.max(0,Number($('#qMachiningCost').value)||0),setup=Math.max(0,Number($('#qSetupCost').value)||0),finish=Math.max(0,Number($('#qFinishCost').value)||0),inspection=Math.max(0,Number($('#qInspectionCost').value)||0),overheadRate=Math.max(0,Number($('#qOverhead').value)||0)/100,marginRate=Math.max(0,Number($('#qMargin').value)||0)/100,direct=material+machining+setup/qty+finish+inspection,auto=direct*(1+overheadRate)*(1+marginRate),mode=item.priceMode||'auto',unit=mode==='manual'&&manual>0?manual:auto;$('#qSubtotal').textContent=money(unit*qty);$('#qCostHint').textContent=mode==='manual'?'手动价格已锁定':'成本构成自动核算';$('#qUnitPrice').disabled=mode!=='manual'};
 $$('[data-price-mode]').forEach(button=>button.onclick=()=>{item.priceMode=button.dataset.priceMode;$$('[data-price-mode]').forEach(node=>node.classList.toggle('active',node===button));refresh()});$$('#quoteEditor input').forEach(input=>input.addEventListener('input',refresh));$('#quoteClose').onclick=closeQuoteEditor;$('#quoteBackdrop').onclick=closeQuoteEditor;$('#quoteSave').onclick=()=>{item.material=$('#qMaterial').value;item.finish=$('#qFinish').value;item.quantity=Math.max(1,Math.round(Number($('#qQuantity').value)||1));item.revision=$('#qRevision').value.trim()||'A';item.unitPrice=Math.max(0,Number($('#qUnitPrice').value)||0);item.costConfig={materialCost:Number($('#qMaterialCost').value)||0,machiningCost:Number($('#qMachiningCost').value)||0,setupCost:Number($('#qSetupCost').value)||0,finishCost:Number($('#qFinishCost').value)||0,inspectionCost:Number($('#qInspectionCost').value)||0,overheadRate:(Number($('#qOverhead').value)||0)/100,marginRate:(Number($('#qMargin').value)||0)/100};closeQuoteEditor();renderTree();if(state.active?.id===item.id)renderCadWorkspace(item);toast(`已同步到项目报价：${item.quantity} 件 · ${money(partCost(item).line)}`)};refresh()}
