function renderProjectQuote(){const host=quoteDrawer(),sheet=host.querySelector('.project-quote-sheet'),parts=state.files.filter(file=>file.part),meta=quoteMeta(),totals=quoteTotals();sheet.innerHTML=`<header class="project-quote-head"><div><small>PROJECT QUOTATION WORKSPACE</small><h2>报价配置与制造 BOM</h2><p>对外报价、成本、图纸关联与导出均使用本页数据。</p></div><div><button id="closeProjectQuote">关闭</button><button id="projectExportXlsx" class="primary">导出 Excel 交付包</button><button id="projectExportPdf" class="primary">导出正式报价单</button></div></header><div class="project-quote-body"><section class="quote-meta-grid"><label>报价编号<input id="qmQuoteNo" value="${esc(meta.quoteNo)}"></label><label>客户名称<input id="qmCustomer" value="${esc(meta.customer)}"></label><label>联系人 / 电话<input id="qmContact" value="${esc(meta.contact)}"></label><label>有效期（天）<input id="qmValidDays" type="number" min="1" value="${meta.validDays}"></label><label>交期<input id="qmLeadTime" value="${esc(meta.leadTime)}"></label><label>税率 %<input id="qmTaxRate" type="number" min="0" step=".1" value="${(meta.taxRate*100).toFixed(1)}"></label><label>运费<input id="qmFreight" type="number" min="0" step=".01" value="${meta.freight}"></label><label>付款条款<input id="qmTerms" value="${esc(meta.paymentTerms)}"></label><label class="quote-meta-notes">报价备注<textarea id="qmNotes">${esc(meta.notes)}</textarea></label></section><div class="bom-actions"><span>${parts.length} 个已解析零件 · 选择后批量套用设置</span><select id="batchMaterial"><option value="">批量材料…</option>${Object.keys(materialDensities).map(name=>`<option>${name}</option>`).join('')}</select><select id="batchFinish"><option value="">批量表面…</option><option>As Machined</option><option>Anodizing (Clear)</option><option>Anodizing (Black)</option><option>Powder Coating</option><option>Passivation</option></select><input id="batchMargin" type="number" min="0" step=".1" placeholder="利润率 %"><button id="applyBatch">应用到选中项</button></div><div class="bom-scroll"><table class="project-bom-table"><thead><tr><th><input id="bomAll" type="checkbox"></th><th>产品号 / 零件</th><th>工艺与材料</th><th>版本</th><th>数量</th><th>图纸 / FAIR</th><th>材料</th><th>加工</th><th>装夹</th><th>质检</th><th>管理费</th><th>利润</th><th>单价</th><th>小计</th><th></th></tr></thead><tbody>${parts.map(item=>{const c=partCost(item),drawings=relatedDrawings(item),fair=drawings.reduce((sum,drawing)=>sum+drawing.results.length,0);return `<tr data-bom-row="${item.id}"><td><input class="bom-check" type="checkbox"></td><td><b>${esc(cadDisplayName(item))}</b><small>${esc(item.name)} · ${item.part.size.map(v=>v.toFixed(1)).join(' × ')} mm</small></td><td><span>${esc(c.basis.process)}</span><small>${esc(item.finish||'As Machined')}</small></td><td>${esc(item.revision||'A')}</td><td><input data-bom-quantity type="number" min="1" value="${c.qty}"></td><td><span>${drawings.length} 张图</span><small>${fair} 项 FAIR</small></td><td>${money(c.material)}</td><td>${money(c.machining)}</td><td>${money(c.setup)}</td><td>${money(c.inspection+c.finish)}</td><td>${money(c.overhead)}</td><td>${money(c.autoUnit-c.direct-c.overhead)}</td><td><b>${money(c.unit)}</b><small>${c.mode==='manual'?'手动锁定':'自动核算'}</small></td><td><b>${money(c.line)}</b></td><td><button data-edit-part="${item.id}">配置</button></td></tr>`}).join('')}</tbody></table></div><section class="quote-totals"><div><span>未税货款</span><b>${money(totals.goods)}</b></div><div><span>运费</span><b>${money(totals.freight)}</b></div><div><span>税额</span><b>${money(totals.tax)}</b></div><div class="grand"><span>含税总计</span><b>${money(totals.total)}</b><small>${meta.currency} · 有效期 ${meta.validDays} 天</small></div></section></div>`;
 $('#closeProjectQuote').onclick=()=>host.classList.add('hidden');$('#bomAll').onchange=event=>$$('.bom-check').forEach(check=>check.checked=event.target.checked);$$('[data-bom-quantity]').forEach(input=>input.onchange=()=>{const item=state.files.find(file=>file.id===input.closest('[data-bom-row]').dataset.bomRow);if(item){item.quantity=Math.max(1,Math.round(Number(input.value)||1));renderProjectQuote();renderTree()}});$$('[data-edit-part]').forEach(button=>button.onclick=()=>{const item=state.files.find(file=>file.id===button.dataset.editPart);if(item)editQuote(item)});$('#applyBatch').onclick=()=>{const chosen=$$('.bom-check:checked').map(check=>state.files.find(file=>file.id===check.closest('[data-bom-row]').dataset.bomRow)).filter(Boolean);if(!chosen.length)return toast('请先选择至少一个 BOM 项');const material=$('#batchMaterial').value,finish=$('#batchFinish').value,margin=$('#batchMargin').value;chosen.forEach(item=>{if(material)item.material=material;if(finish)item.finish=finish;if(margin!==''){item.costConfig??={};item.costConfig.marginRate=Math.max(0,Number(margin)||0)/100}});renderProjectQuote();renderTree();toast(`已将报价设置应用到 ${chosen.length} 个零件`)};$$('#projectQuoteDrawer input,#projectQuoteDrawer textarea').filter(input=>!input.closest('.bom-scroll')&&!input.closest('.bom-actions')).forEach(input=>input.addEventListener('change',()=>{syncQuoteMeta();renderProjectQuote();renderTree()}));$('#projectExportXlsx').onclick=()=>{syncQuoteMeta();exportQuoteWorkbook()};$('#projectExportPdf').onclick=()=>{syncQuoteMeta();exportFormalQuotePdf()}}
