function exportFormalQuotePdf(){const parts=state.files.filter(file=>file.part);if(!parts.length)return toast('需要至少一个已解析的 CAD 零件');const meta=quoteMeta(),totals=quoteTotals(),doc=new jsPDF({unit:'mm',format:'a4'}),today=new Date().toLocaleDateString('zh-CN'),pageHeader=page=>{doc.setFillColor(23,33,43);doc.rect(0,0,210,31,'F');doc.setTextColor(255,255,255);doc.setFontSize(18);doc.text('MFGGO  MANUFACTURING QUOTATION',14,14);doc.setFontSize(8);doc.text(meta.quoteNo+'  |  '+today+'  |  Page '+page,14,22);doc.setTextColor(36,49,60)},tableHead=y=>{doc.setFillColor(36,82,106);doc.rect(12,y,186,8,'F');doc.setTextColor(255,255,255);doc.setFontSize(7);['No.','Part number / part','Material & process','Rev.','Qty','Unit price','Subtotal'].forEach((text,index)=>doc.text(text,[14,30,78,126,138,151,176][index],y+5));doc.setTextColor(36,49,60)};let page=1;pageHeader(page);doc.setFontSize(15);doc.text('FORMAL MACHINING QUOTATION',14,43);doc.setFontSize(8);doc.setTextColor(95,112,126);doc.text('Customer: '+meta.customer+'    Contact: '+(meta.contact||'-'),14,51);doc.text('Lead time: '+meta.leadTime+'    Validity: '+meta.validDays+' days',14,57);doc.setTextColor(36,49,60);tableHead(67);let y=81;totals.lines.forEach((c,index)=>{if(y>248){doc.addPage();page++;pageHeader(page);tableHead(40);y=54}const item=parts[index];doc.setDrawColor(221,228,233);doc.line(12,y+10,198,y+10);doc.setFontSize(7);doc.text(String(index+1),14,y);doc.text(String(cadDisplayName(item)).slice(0,25),30,y);doc.text(((item.material||c.basis.material).replace('Aluminum ','AL '))+' / '+c.basis.process,78,y,{maxWidth:44});doc.text(item.revision||'A',126,y);doc.text(String(c.qty),138,y);doc.text(money(c.unit),151,y);doc.text(money(c.line),176,y);doc.setTextColor(100,116,139);doc.setFontSize(6.3);doc.text(item.part.size.map(v=>v.toFixed(1)).join(' x ')+' mm | '+(item.finish||'As Machined')+' | '+relatedDrawings(item).length+' drawings / '+relatedDrawings(item).reduce((sum,file)=>sum+file.results.length,0)+' FAIR items',30,y+5);doc.setTextColor(36,49,60);y+=16});if(y>232){doc.addPage();page++;pageHeader(page);y=47}doc.setFillColor(240,246,249);doc.roundedRect(122,y,76,38,2,2,'F');doc.setFontSize(8);doc.text('Goods subtotal',128,y+9);doc.text('Freight',128,y+16);doc.text('Tax '+(meta.taxRate*100).toFixed(1)+'%',128,y+23);doc.setFontSize(11);doc.text('TOTAL',128,y+32);doc.setFontSize(8);doc.text(money(totals.goods),192,y+9,{align:'right'});doc.text(money(totals.freight),192,y+16,{align:'right'});doc.text(money(totals.tax),192,y+23,{align:'right'});doc.setFontSize(12);doc.text(money(totals.total),192,y+32,{align:'right'});y+=49;doc.setDrawColor(206,216,223);doc.line(12,y,198,y);doc.setFontSize(8);doc.setTextColor(72,88,101);doc.text('TERMS & DELIVERY',12,y+9);doc.setFontSize(7);const terms=['Payment: '+meta.paymentTerms,'Notes: '+meta.notes,'This quotation is based on local B-Rep geometry analysis. Tolerances, special fixtures, heat treatment and inspection shall be confirmed against released drawings.'];let ty=y+15;terms.forEach(line=>{const wrapped=doc.splitTextToSize(line,178);doc.text(wrapped,12,ty);ty+=wrapped.length*4+3});doc.setDrawColor(170,183,192);doc.line(14,275,76,275);doc.line(130,275,194,275);doc.setFontSize(7);doc.text('Prepared by / Date',14,280);doc.text('Customer acceptance / Date',130,280);doc.save(meta.quoteNo+'_正式报价单.pdf');toast('已导出含税、运费、条款和签字区的正式报价单')}
