async function loadQuotePdfFont(doc){if(!quotePdfFontData){const response=await fetch('./fonts/SimHei.ttf');if(!response.ok)throw new Error('中文字体文件不可用');const blob=await response.blob();quotePdfFontData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)})}doc.addFileToVFS('SimHei.ttf',quotePdfFontData);doc.addFont('SimHei.ttf','MFGGO','normal');doc.setFont('MFGGO')}
