function refreshProjectQuoteTotals(){const host=$('#projectQuoteDrawer .quote-totals');if(!host)return;const totals=quoteTotals(),meta=quoteMeta();host.innerHTML=`<div><span>未税货款</span><b>${money(totals.goods)}</b></div><div><span>运费</span><b>${money(totals.freight)}</b></div><div><span>税额</span><b>${money(totals.tax)}</b></div><div class="grand"><span>含税总计</span><b>${money(totals.total)}</b><small>${meta.currency} · 有效期 ${meta.validDays} 天</small></div>`}
const renderProjectQuoteWithLiveMeta=renderProjectQuote;renderProjectQuote=()=>{renderProjectQuoteWithLiveMeta();$$('#projectQuoteDrawer .quote-meta-grid input,#projectQuoteDrawer .quote-meta-grid textarea').forEach(input=>input.addEventListener('input',()=>{syncQuoteMeta();refreshProjectQuoteTotals()}));$$('#projectQuoteDrawer [data-bom-quantity]').forEach(input=>input.oninput=()=>{clearTimeout(input.quoteTimer);input.quoteTimer=setTimeout(()=>{const item=state.files.find(file=>file.id===input.closest('[data-bom-row]').dataset.bomRow);if(item){item.quantity=Math.max(1,Math.round(Number(input.value)||1));renderProjectQuote();renderTree()}},250)})};
